#!/bin/sh
# Name: Sidle
# Author: Ziwei Huang
# Icon: data:image/png;base64,
# DontUseFBInk

# One tap from the home library straight into the picker, bypassing
# KUAL > Sidle. Generated by scripts/make-scriptlet.sh — edit that, not this.
# The wrapper is the same one KUAL's menu entry runs, so the staged
# self-update swap and launch logging stay single-sourced in the extension.
if pidof sidle >/dev/null 2>&1; then
    exit 0
fi
nohup sh -c 'sleep 1; exec /mnt/us/extensions/sidle/bin/sidle.sh' >/dev/null 2>&1 &
